import Model from 'flarum/common/Model';

/** `member-map-trips`: "visiting Chicago, Dec 3–7". */
export default class MemberMapTrip extends Model {
  label = Model.attribute('label');
  starts = Model.attribute('starts');
  ends = Model.attribute('ends');
}
flarum.reg.add('ernestdefoe-member-map', 'forum/models/MemberMapTrip', MemberMapTrip);