import Model from 'flarum/common/Model';
/** `member-map-locations`: the viewer's own place, keyed by their user id. */
export default class MemberMapLocation extends Model {
  lat = Model.attribute('lat');
  lng = Model.attribute('lng');
  label = Model.attribute('label');
  precision = Model.attribute('precision');
  profile = Model.attribute('profile');
  membersOnly = Model.attribute('membersOnly');
  listed = Model.attribute('listed');
  place() {
    return {
      lat: this.lat(),
      lng: this.lng(),
      label: this.label(),
      precision: this.precision(),
      profile: this.profile(),
      membersOnly: this.membersOnly(),
      listed: this.listed()
    };
  }
}
flarum.reg.add('ernestdefoe-member-map', 'forum/models/MemberMapLocation', MemberMapLocation);