import Model from 'flarum/common/Model';

/** `member-map-stats`: the "Where we are" widget's counts. */
export default class MemberMapStats extends Model {
  members = Model.attribute('members');
  countries = Model.attribute('countries');
}
flarum.reg.add('ernestdefoe-member-map', 'forum/models/MemberMapStats', MemberMapStats);