import Model from 'flarum/common/Model';

/** `member-map-meetups`: a place, a local time and a discussion. */
export default class MemberMapMeetup extends Model {
  title = Model.attribute('title');
  label = Model.attribute('label');
  discussionId = Model.attribute('discussionId');
  discussionSlug = Model.attribute('discussionSlug');
}
flarum.reg.add('ernestdefoe-member-map', 'forum/models/MemberMapMeetup', MemberMapMeetup);